package com.comandos.reservation.controller;import static org.junit.jupiter.api.Assertions.assertEquals;import java.math.*;import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.jdbc.core.JdbcTemplate;import tools.jackson.databind.*;import tools.jackson.databind.json.JsonMapper;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:h2:mem:reservation-tests;MODE=Oracle;DB_CLOSE_DELAY=-1","logging.level.root=WARN","debug=false"})class ReservationApiTests{@LocalServerPort int port;@Autowired JdbcTemplate jdbc;final HttpClient client=HttpClient.newHttpClient();final JsonMapper json=JsonMapper.builder().build();record R(int status,JsonNode body,String raw){}record S(long org,long unit,long asset,long lot,long balance){}
 @Test void reservesAndCancelsAssetsAndLotQuantities()throws Exception{var s=setup();var payload=payload(s);var created=request("POST","reservations",payload);assertEquals(200,created.status(),created.raw());long id=created.body().get("id").asLong();assertEquals("BLOCKED",assetStatus(s.asset()));assertEquals("7.5000",decimal("select available from erp_stock_balance where id=?",s.balance()));assertEquals("2.5000",decimal("select reserved from erp_stock_balance where id=?",s.balance()));assertEquals("10.0000",decimal("select available_quantity from erp_stock_lot where id=?",s.lot()));assertEquals(id,request("POST","reservations",payload).body().get("id").asLong());var cancelled=request("POST","reservations/"+id+"/cancel",null);assertEquals("CANCELLED",cancelled.body().get("statusCode").asText());assertEquals("AVAILABLE",assetStatus(s.asset()));assertEquals("10.0000",decimal("select available from erp_stock_balance where id=?",s.balance()));assertEquals("0.0000",decimal("select reserved from erp_stock_balance where id=?",s.balance()));}
 @Test void expirationRequiresElapsedEndAndReleasesStock()throws Exception{var s=setup();long id=request("POST","reservations",payload(s)).body().get("id").asLong();assertEquals(400,request("POST","reservations/"+id+"/expire",null).status());jdbc.update("update erp_inventory_reservation set ends_at=? where id=?",LocalDateTime.now().minusMinutes(1),id);assertEquals("EXPIRED",request("POST","reservations/"+id+"/expire",null).body().get("statusCode").asText());assertEquals("AVAILABLE",assetStatus(s.asset()));}
 @Test void statusTypesAreRegistrationsAndProtectedDefaultsCannotBeDeleted()throws Exception{var list=request("GET","inventory/reservation-status-types",null);assertEquals(3,list.body().get("totalElements").asInt());create("inventory/reservation-status-types",Map.of("code","AWAITING_APPROVAL","name","Awaiting approval","active",true,"terminal",false,"displayOrder",5));long active=list.body().get("content").get(0).get("id").asLong();assertEquals(400,request("DELETE","inventory/reservation-status-types/"+active+"?version=0",null).status());}
 private Map<String,Object>payload(S s){return Map.of("requestId",uuid(),"organizationId",s.org(),"unitId",s.unit(),"purpose","Training allocation","startsAt",LocalDateTime.now().plusMinutes(1).withNano(0).toString(),"endsAt",LocalDateTime.now().plusDays(1).withNano(0).toString(),"items",List.of(Map.of("assetId",s.asset(),"quantity",1),Map.of("balanceId",s.balance(),"quantity","2.5000")));}private S setup()throws Exception{long o=create("core/organizations",Map.of("name",uuid(),"nature","Public safety","publicOrganization",true,"active",true)),u=create("core/units",Map.of("organizationId",o,"code",uuid(),"name","Unit","type","Unit")),ca=create("inventory/categories",Map.of("name",uuid(),"family","OPTICAL","serialized",true,"lotControlled",false,"consumable",false)),cl=create("inventory/categories",Map.of("name",uuid(),"family","AMMUNITION","serialized",false,"lotControlled",true,"consumable",true)),b=create("inventory/brands",Map.of("name",uuid(),"manufacturer","Maker")),ma=create("inventory/models",Map.of("categoryId",ca,"brandId",b,"name","Sight","unitOfMeasure","EA","sku",uuid(),"listPrice","1")),ml=create("inventory/models",Map.of("categoryId",cl,"brandId",b,"name","Cartridge","unitOfMeasure","EA","sku",uuid(),"listPrice","1")),l=create("inventory/locations",Map.of("organizationId",o,"unitId",u,"name","Vault","type","Controlled","controlled",true)),a=create("inventory/assets",Map.of("modelId",ma,"locationId",l,"assetCode",uuid(),"serialNumber",uuid(),"condition","GOOD","status","AVAILABLE","currentValue","1")),lot=create("inventory/lots",Map.of("modelId",ml,"openingLocationId",l,"lotNumber",uuid(),"initialQuantity","10"));long balance=jdbc.queryForObject("select id from erp_stock_balance where lot_id=?",Long.class,lot);return new S(o,u,a,lot,balance);}
 private String assetStatus(long id){return jdbc.queryForObject("select status from erp_asset_item where id=?",String.class,id);}private String decimal(String q,Object...a){return jdbc.queryForObject(q,BigDecimal.class,a).setScale(4).toPlainString();}private long create(String p,Object b)throws Exception{var r=request("POST",p,b);assertEquals(201,r.status(),r.raw());return r.body().get("id").asLong();}private R request(String m,String p,Object b)throws Exception{var q=HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/api/erp/"+p)).header("Content-Type","application/json").method(m,b==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(b))).build();var x=client.send(q,HttpResponse.BodyHandlers.ofString());return new R(x.statusCode(),x.body().isBlank()?null:json.readTree(x.body()),x.body());}private String uuid(){return UUID.randomUUID().toString();}}
